package Assignments;

public class Assignment31 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Substraction: " + Math.subtractExact(100, 20));
		
		System.out.println("Multiply: " + Math.multiplyExact(10, 20));
		
		System.out.println("Addition: " + Math.addExact(10, 20));
		
		  System.out.println("Maximum: " + Math.max(10, 20));

	        System.out.println("Minimum: " + Math.min(10, 20));

	        System.out.println("Square root: " + Math.sqrt(25));

	        System.out.println("Power: " + Math.pow(2, 3));

	        System.out.println("Absolute value: " + Math.abs(-15));

	        System.out.println("Round: " + Math.round(10.6));

	        System.out.println("Ceiling: " + Math.ceil(10.2));

	        System.out.println("Floor: " + Math.floor(10.8));

	        System.out.println("Random number: " + Math.random());
	}

}
